mapper.select:
select config_id, user_id, table_key, config_content,
       create_by, create_time, update_by, update_time
from sys_user_table_column_config
where user_id = #{userId}
  and table_key = #{tableKey}
limit 1

mapper.delete:
delete from sys_user_table_column_config
where user_id = #{userId}
  and table_key = #{tableKey}
